13	// View reads a published release manifest and renders it.
14	//
15	// It makes no source-repository, GitOps-remote, or environment change. It does
16	// refresh the local cached GitOps checkout to locate the component metadata;
17	// that cache is an implementation detail, not deployment state. View exists so
18	// generated notes can be sanity-checked before anything is deployed from them.
19	func View(ctx context.Context, opts Options) error {
20		opts.applyDefaults()
21	
22		if opts.Version == "" {
23			return fmt.Errorf("a version is required")
24		}
25		if err := command.RequireBinaries("git"); err != nil {
26			return err
27		}
28	
29		cfg, err := config.Load()
30		if err != nil {
31			return err
32		}
33		resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo})
34		repoURL, err := resolved.RequireGitopsRepo()
35		if err != nil {
36			return err
37		}
38	
39		repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot})
40		if err != nil {
41			return err
42		}
43		defer repo.Close()
44	
45		coord, err := gitops.FindComponent(repo.Root, opts.Component, opts.Domain, opts.System)
46		if err != nil {
47			return err
48		}
49		comp, err := gitops.LoadComponentConfig(gitops.JoinRel(repo.Root, coord.RelPath()))
50		if err != nil {
51			return err
52		}
53		if len(comp.Images) == 0 {
54			return fmt.Errorf("%s declares no images, so it has no releases", coord)
55		}
56	
57		reg, err := NewRegistry(opts.UserAgent)
58		if err != nil {
59			return err
60		}
61	
62		ref := Ref(ReleasesRepo(comp.Images[0].Name), opts.Version)
63		m, err := Pull(ctx, reg, ref)
64		if err != nil {
65			return err
66		}
67		// The requested OCI tag and the manifest's self-described version must
68		// agree. A retagged artifact must not be presented as a different release.
69		if m.Version != opts.Version {
70			return fmt.Errorf("%s is tagged as release %s, but its manifest declares version %s", ref, opts.Version, m.Version)
71		}
72	
73		if opts.OutputFormat == OutputJSON {
74			enc := json.NewEncoder(opts.Stdout)
75			enc.SetIndent("", "  ")
76			return enc.Encode(m)
77		}
78		return renderManifest(opts.Stdout, m)
79	}
