1	package release
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"strings"
8	
9		"github.com/integrio-intropy/intropy-cli/internal/git"
10	)
11	
12	// InitialNotes is what a release with no basis for comparison says, rather
13	// than leaving the notes blank and letting a reader guess.
14	const InitialNotes = "Initial release."
15	
16	// Ancestry answers whether one commit descends from another. It is the seam
17	// that lets predecessor selection be tested without a real repository, and is
18	// satisfied by git.Client.
19	type Ancestry interface {
20		IsAncestor(ctx context.Context, ancestor, descendant string) (bool, error)
21	}
22	
23	// PreviousRelease finds the release that commit most recently descends from.
24	//
25	// The registry is the authority for which releases exist — a git tag that
26	// failed to push must not hide one — but "which release does this commit
27	// descend from" is a lineage question, so ancestry decides between the
28	// candidates rather than a version sort. Sorting by version breaks the moment
29	// history branches: a hotfix cut from a maintenance branch would take the
30	// newer release on the mainline as its predecessor and report a changelog full
31	// of commits it does not contain.
32	//
33	// Releases the commit does not descend from are skipped. Of those it does, the
34	// nearest wins — the one every other candidate is an ancestor of.
35	//
36	// The version being released is excluded from the candidates. Re-running
37	// create for a version that already exists must reproduce the manifest it
38	// published the first time, and a release whose own commit is an ancestor of
39	// itself — git counts equal commits as ancestors — would otherwise become its
40	// own predecessor and change the basis on every retry.
41	//
42	// A nil manifest with a nil error means there is no predecessor: either
43	// nothing has been released, or nothing released is an ancestor.
44	func PreviousRelease(ctx context.Context, reg Registry, anc Ancestry, releasesRepo, commit, excludeVersion string) (*Manifest, error) {
45		versions, err := ListVersions(ctx, reg, releasesRepo)
46		if err != nil {
47			// Never released: the repository does not exist yet.
48			if errors.Is(err, ErrNotFound) {
49				return nil, nil
50			}
51			return nil, fmt.Errorf("list releases in %s: %w", releasesRepo, err)
52		}
53	
54		var candidates []*Manifest
55		for _, v := range versions {
56			if v == excludeVersion {
57				continue
58			}
59			m, err := Pull(ctx, reg, Ref(releasesRepo, v))
60			if err != nil {
61				// One unreadable tag must not make every later release
62				// unchangeloggable. Skip it; the basis simply reaches further back.
63				if errors.Is(err, ErrNotRelease) || errors.Is(err, ErrNotFound) {
64					continue
65				}
66				return nil, fmt.Errorf("read release %s: %w", v, err)
67			}
68	
69			descends, err := anc.IsAncestor(ctx, m.Source.Commit, commit)
70			if err != nil {
71				// A release built from a commit this clone has never seen is not
72				// an ancestor as far as we can tell, and not a reason to fail.
73				continue
74			}
75			if descends {
76				candidates = append(candidates, m)
77			}
78		}
79	
80		return nearest(ctx, anc, candidates)
81	}
82	
83	// nearest returns the candidate that every other candidate is an ancestor of.
84	func nearest(ctx context.Context, anc Ancestry, candidates []*Manifest) (*Manifest, error) {
85		if len(candidates) == 0 {
86			return nil, nil
87		}
88	
89		best := candidates[0]
90		for _, c := range candidates[1:] {
91			// c is nearer when best is an ancestor of it.
92			nearer, err := anc.IsAncestor(ctx, best.Source.Commit, c.Source.Commit)
93			if err != nil {
94				return nil, err
95			}
96			if nearer {
97				best = c
98			}
99		}
100		return best, nil
101	}
102	
103	// Changelog lists the commits in from..to that touched sourcePaths.
104	//
105	// from is exclusive and to is inclusive, matching git's range syntax: the
106	// predecessor's own commit is already released, so it is not part of what
107	// changed.
108	func Changelog(ctx context.Context, g git.Client, from, to string, sourcePaths []string) ([]Change, error) {
109		commits, err := g.Log(ctx, from+".."+to, sourcePaths...)
110		if err != nil {
111			return nil, err
112		}
113	
114		changes := make([]Change, 0, len(commits))
115		for _, c := range commits {
116			changes = append(changes, Change{Commit: c.SHA, Subject: c.Subject})
117		}
118		return changes, nil
119	}
120	
121	// RenderNotes turns the changelog into the manifest's notes.
122	func RenderNotes(changes []Change, basis ChangeBasis) string {
123		if basis.Kind == BasisInitial && len(changes) == 0 {
124			return InitialNotes
125		}
126		if len(changes) == 0 {
127			return ""
128		}
129	
130		var b strings.Builder
131		for _, c := range changes {
132			fmt.Fprintf(&b, "- %s\n", c.Subject)
133		}
134		return b.String()
135	}
