3	import (
4		"fmt"
5		"io"
6		"strings"
7		"text/tabwriter"
8	)
9	
10	// renderCreated reports what Create did.
11	func renderCreated(w io.Writer, r Result) error {
12		verb := "published"
13		if !r.Created {
14			verb = "already published"
15		}
16		fmt.Fprintf(w, "%s %s %s\n", verb, r.Component, r.Version)
17		fmt.Fprintf(w, "  %s\n", r.Ref)
18		if r.Digest != "" {
19			fmt.Fprintf(w, "  %s\n", r.Digest)
20		}
21		if r.Tagged {
22			fmt.Fprintf(w, "  tag %s\n", r.Tag)
23		}
24		fmt.Fprintln(w)
25		return renderManifest(w, r.Manifest)
26	}
27	
28	// renderManifest is the human view of a release.
29	func renderManifest(w io.Writer, m *Manifest) error {
30		if m == nil {
31			return nil
32		}
33	
34		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
35		fmt.Fprintf(tw, "component\t%s\n", m.Component)
36		fmt.Fprintf(tw, "version\t%s\n", m.Version)
37		fmt.Fprintf(tw, "created\t%s\n", m.CreatedAt.Format("2006-01-02 15:04:05 UTC"))
38		if m.CreatedBy != "" {
39			fmt.Fprintf(tw, "created by\t%s\n", m.CreatedBy)
40		}
41		fmt.Fprintf(tw, "commit\t%s\n", m.Source.Commit)
42		for i, img := range m.Images {
43			label := "images"
44			if i > 0 {
45				label = ""
46			}
47			fmt.Fprintf(tw, "%s\t%s@%s\n", label, img.Name, img.Digest)
48		}
49		fmt.Fprintf(tw, "basis\t%s\n", m.ChangeBasis.Describe())
50		if err := tw.Flush(); err != nil {
51			return err
52		}
53	
54		notes := strings.TrimRight(m.Notes, "\n")
55		if notes == "" {
56			return nil
57		}
58		fmt.Fprintf(w, "\nnotes:\n%s\n", indent(notes, "  "))
59		return nil
60	}
61	
62	func indent(s, prefix string) string {
63		lines := strings.Split(s, "\n")
64		for i, line := range lines {
65			lines[i] = prefix + line
66		}
67		return strings.Join(lines, "\n")
68	}
