19	// createFixture is everything Create needs: a GitOps repository describing one
20	// component, a source repository whose HEAD is pushed, a config file pointing
21	// at the GitOps origin, and an in-memory registry holding the images CI
22	// "published" for that commit.
23	type createFixture struct {
24		gitopsOrigin string
25		sourceDir    string
26		sourceOrigin string
27		cacheRoot    string
28		image        string
29		reg          *registry.Client
30		registryHost string
31	}
32	
33	func newCreateFixture(t *testing.T) *createFixture {
34		t.Helper()
35	
36		reg, srv := testRegistry(t)
37		image := srv.Host + "/integrations/order-extractor"
38	
39		gitopsOrigin := gitopstest.NewRepo(t, gitopstest.Component{
40			Coordinate:   "orders/order-flow/order-extractor",
41			Image:        image,
42			Environments: []string{"dev", "prod"},
43		})
44	
45		sourceOrigin := gittest.NewRepo(t, "main")
46		gittest.Commit(t, sourceOrigin, filepath.Join("component", "app.cs"), "// v1\n", "Initial component")
47	
48		sourceDir := filepath.Join(t.TempDir(), "src")
49		if err := git.Clone(context.Background(), command.ExecRunner{}, sourceOrigin, sourceDir); err != nil {
50			t.Fatal(err)
51		}
52		gittest.Run(t, sourceDir, "config", "user.email", "test@example.com")
53		gittest.Run(t, sourceDir, "config", "user.name", "Test")
54		gittest.Run(t, sourceDir, "config", "commit.gpgsign", "false")
55	
56		cfgHome := t.TempDir()
57		t.Setenv("XDG_CONFIG_HOME", cfgHome)
58		t.Setenv("INTROPY_GITOPS_REPO", "")
59		t.Setenv("GITLAB_USER_EMAIL", "robin.hultman@integrio.se")
60		gittest.WriteFile(t, filepath.Join(cfgHome, "intropy", "config.yaml"), "gitopsRepo: "+gitopsOrigin+"\n")
61	
62		f := &createFixture{
63			gitopsOrigin: gitopsOrigin,
64			sourceDir:    sourceDir,
65			sourceOrigin: sourceOrigin,
66			cacheRoot:    t.TempDir(),
67			image:        image,
68			reg:          reg,
69			registryHost: srv.Host,
70		}
71		f.stubRegistry(t)
72		f.publishImage(t)
73	
74		// A fixed clock keeps a manifest reproducible across runs.
75		original := now
76		now = func() time.Time { return time.Date(2026, 7, 27, 10, 0, 0, 0, time.UTC) }
77		t.Cleanup(func() { now = original })
78	
79		return f
80	}
81	
82	// stubRegistry points the package at the in-memory registry.
83	func (f *createFixture) stubRegistry(t *testing.T) {
84		t.Helper()
85		original := NewRegistry
86		NewRegistry = func(string) (Registry, error) { return f.reg, nil }
87		t.Cleanup(func() { NewRegistry = original })
88	}
