90	// publishImage pushes an image tagged sha-<HEAD>, standing in for CI.
91	func (f *createFixture) publishImage(t *testing.T) {
92		t.Helper()
93		head := gittest.HEAD(t, f.sourceDir)
94		if _, err := f.reg.PushArtifact(context.Background(), f.image+":sha-"+head, registry.Artifact{
95			ArtifactType: "application/vnd.test.image",
96			Layers:       []registry.Blob{{MediaType: "application/vnd.oci.image.layer.v1.tar", Data: []byte(head)}},
97		}); err != nil {
98			t.Fatal(err)
99		}
100	}
