102	// commitAndPush adds a commit to the source and publishes an image for it.
103	func (f *createFixture) commitAndPush(t *testing.T, path, subject string) {
104		t.Helper()
105		gittest.Commit(t, f.sourceDir, filepath.Join("component", path), "// "+subject+"\n", subject)
106		gittest.Run(t, f.sourceDir, "push", "--quiet", "origin", "main")
107		f.publishImage(t)
108	}
