127	// create runs Create and decodes the JSON result.
128	func (f *createFixture) create(t *testing.T, version string) (Result, string) {
129		t.Helper()
130		var stdout, stderr bytes.Buffer
131		if err := Create(context.Background(), f.options(version, &stdout, &stderr)); err != nil {
132			t.Fatalf("Create(%s): %v\nstderr: %s", version, err, stderr.String())
133		}
134		var r Result
135		if err := json.Unmarshal(stdout.Bytes(), &r); err != nil {
136			t.Fatalf("decode result: %v\nstdout: %s", err, stdout.String())
137		}
138		return r, stderr.String()
139	}
