141	func TestCreatePublishesAManifest(t *testing.T) {
142		f := newCreateFixture(t)
143	
144		r, _ := f.create(t, "1.0.0")
145	
146		if !r.Created {
147			t.Error("Created = false on a first publish")
148		}
149		if r.Digest == "" {
150			t.Error("no digest reported")
151		}
152		if r.Manifest.Component != "order-extractor" || r.Manifest.Version != "1.0.0" {
153			t.Errorf("manifest = %+v", r.Manifest)
154		}
155		if len(r.Manifest.Images) != 1 || !strings.HasPrefix(r.Manifest.Images[0].Digest, "sha256:") {
156			t.Errorf("images = %+v, want one pinned digest", r.Manifest.Images)
157		}
158		if r.Manifest.Source.Commit != gittest.HEAD(t, f.sourceDir) {
159			t.Errorf("source.commit = %s, want HEAD", r.Manifest.Source.Commit)
160		}
161		if r.Manifest.CreatedBy != "robin.hultman@integrio.se" {
162			t.Errorf("createdBy = %q", r.Manifest.CreatedBy)
163		}
164	
165		// It must be readable back as a release.
166		got, err := Pull(context.Background(), f.reg, r.Ref)
167		if err != nil {
168			t.Fatal(err)
169		}
170		if !got.SameRelease(r.Manifest) {
171			t.Error("the published manifest differs from the reported one")
172		}
173	}
