175	// The first release has no predecessor, so it says so rather than leaving an
176	// empty changes[] to be misread as "nothing changed".
177	func TestFirstReleaseRecordsInitialBasis(t *testing.T) {
178		f := newCreateFixture(t)
179	
180		r, _ := f.create(t, "1.0.0")
181	
182		if r.Manifest.ChangeBasis.Kind != BasisInitial {
183			t.Errorf("changeBasis.kind = %q, want %q", r.Manifest.ChangeBasis.Kind, BasisInitial)
184		}
185		if len(r.Manifest.Changes) != 0 {
186			t.Errorf("changes = %+v, want none", r.Manifest.Changes)
187		}
188		if r.Manifest.Notes != InitialNotes {
189			t.Errorf("notes = %q, want %q", r.Manifest.Notes, InitialNotes)
190		}
191	}
