193	func TestSecondReleaseMeasuresFromTheFirst(t *testing.T) {
194		f := newCreateFixture(t)
195		first, _ := f.create(t, "1.0.0")
196	
197		f.commitAndPush(t, "b.cs", "Handle empty payloads")
198		second, _ := f.create(t, "1.0.1")
199	
200		if second.Manifest.ChangeBasis.Kind != BasisRelease {
201			t.Fatalf("changeBasis.kind = %q, want %q", second.Manifest.ChangeBasis.Kind, BasisRelease)
202		}
203		if second.Manifest.ChangeBasis.Version != "1.0.0" {
204			t.Errorf("basis version = %q, want 1.0.0", second.Manifest.ChangeBasis.Version)
205		}
206		if second.Manifest.ChangeBasis.Commit != first.Manifest.Source.Commit {
207			t.Errorf("basis commit = %s, want the first release's commit", second.Manifest.ChangeBasis.Commit)
208		}
209		if len(second.Manifest.Changes) != 1 || second.Manifest.Changes[0].Subject != "Handle empty payloads" {
210			t.Errorf("changes = %+v, want the one new commit", second.Manifest.Changes)
211		}
212		if !strings.Contains(second.Manifest.Notes, "Handle empty payloads") {
213			t.Errorf("notes = %q", second.Manifest.Notes)
214		}
215	}
