217	// A retry after a partial run must recognise its own earlier work rather than
218	// publishing a second manifest or refusing.
219	func TestCreateTwiceIsOneManifest(t *testing.T) {
220		f := newCreateFixture(t)
221	
222		first, _ := f.create(t, "1.0.0")
223		second, stderr := f.create(t, "1.0.0")
224	
225		if second.Created {
226			t.Error("Created = true on a repeat run; the release already existed")
227		}
228		if second.Digest != first.Digest {
229			t.Errorf("digest changed on retry: %s then %s", first.Digest, second.Digest)
230		}
231		if !strings.Contains(stderr, "already published") {
232			t.Errorf("stderr should say the release already existed, got %q", stderr)
233		}
234	
235		versions, err := ListVersions(context.Background(), f.reg, ReleasesRepo(f.image))
236		if err != nil {
237			t.Fatal(err)
