244	// The tag is the one thing a retry can repair, so deleting it and re-running
245	// must put it back without touching the manifest.
246	func TestCreateRepairsMissingTag(t *testing.T) {
247		f := newCreateFixture(t)
248		first, _ := f.create(t, "1.0.0")
249	
250		tagName := TagName("order-extractor", "1.0.0")
251		gittest.Run(t, f.sourceDir, "tag", "-d", tagName)
252		gittest.Run(t, f.sourceOrigin, "tag", "-d", tagName)
253	
254		second, _ := f.create(t, "1.0.0")
255	
256		if second.Created {
257			t.Error("the manifest was republished; only the tag needed repair")
258		}
259		if !second.Tagged {
260			t.Error("the tag was not repaired")
261		}
262		if second.Digest != first.Digest {
263			t.Error("the manifest digest changed while repairing a tag")
264		}
265		if got := gittest.Run(t, f.sourceOrigin, "tag", "-l", tagName); got != tagName {
266			t.Errorf("tag %s is still missing from the origin", tagName)
267		}
268	}
