270	// A version is a permanent name for one set of bits. Reusing it for different
271	// bits must be refused, not silently overwritten.
272	func TestCreateRefusesDifferentManifestAtSameVersion(t *testing.T) {
273		f := newCreateFixture(t)
274		f.create(t, "1.0.0")
275	
276		f.commitAndPush(t, "b.cs", "Different bits")
277	
278		var stdout, stderr bytes.Buffer
279		err := Create(context.Background(), f.options("1.0.0", &stdout, &stderr))
280		if err == nil {
281			t.Fatal("Create() reused a version for a different release")
282		}
283		for _, want := range []string{"already exists", "immutable"} {
284			if !strings.Contains(err.Error(), want) {
285				t.Errorf("error %q should mention %q", err, want)
286			}
287		}
288	}
