290	func TestCreatePushesAnAnnotatedTag(t *testing.T) {
291		f := newCreateFixture(t)
292	
293		r, _ := f.create(t, "1.4.2")
294	
295		tagName := TagName("order-extractor", "1.4.2")
296		if r.Tag != tagName {
297			t.Errorf("Tag = %q, want %q", r.Tag, tagName)
298		}
